"""Offline project-scoped history tests. The standalone native proof is generated by tests/fixtures/make_hermes_run_history.py."""
import concurrent.futures
import json
import os
import shutil
import sqlite3
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path
from unittest.mock import patch

from scripts.nexus_run_history.source import observe
from scripts.nexus_run_history.store import correlate_session, ingest, inspect_task, query
from scripts.nexus_session_usage.snapshot import UsageError

SHA = "a" * 40
PR = "https://github.com/org/example/pull/9"


def receipt(pr=PR, sha=SHA):
    return {"ok": True, "classification": "success", "head_sha": sha, "pr_url": pr,
            "required": [{"context": "private-check-name", "app_id": None}],
            "checks": [{"name": "private-check-name", "classification": "success", "head_sha": sha,
                        "id": 4, "url": "https://test.invalid/private", "conclusion": "success"}]}


def make_board(path, project="ProjectA", task="t_example", pr=PR):
    with sqlite3.connect(path) as db:
        db.executescript("""
            CREATE TABLE tasks(id TEXT PRIMARY KEY,project_id TEXT,status TEXT,session_id TEXT,completion_contract TEXT);
            CREATE TABLE task_runs(id INTEGER PRIMARY KEY,task_id TEXT,status TEXT,outcome TEXT,started_at INTEGER,ended_at INTEGER,
                                   summary TEXT,metadata TEXT);
            CREATE TABLE task_events(id INTEGER PRIMARY KEY,task_id TEXT,run_id INTEGER,kind TEXT,payload TEXT,created_at INTEGER);
        """)
        db.execute("INSERT INTO tasks VALUES(?,?,?,?,?)", (task, project, "done", "origin-5", pr))
        db.execute("INSERT INTO task_runs VALUES(1,?,'done','completed',10,20,'PRIVATE SUMMARY','SECRET')", (task,))
        events = [(1, None, "created", {"project_id": project, "workspace_path": "/private/path"}, 9),
                  (2, 1, "claimed", {}, 10), (3, 1, "pr_acceptance", receipt(pr), 19),
                  (4, 1, "completed", {"summary": "PRIVATE SUMMARY"}, 20)]
        db.executemany("INSERT INTO task_events VALUES(?,?,?,?,?,?)",
                       [(eid, task, run, kind, json.dumps(payload), created) for eid, run, kind, payload, created in events])


class RunHistoryTests(unittest.TestCase):
    def setUp(self):
        td = tempfile.TemporaryDirectory()
        self.addCleanup(td.cleanup)
        self.root = Path(td.name)
        self.board = self.root / "board.db"
        self.store = self.root / "history.db"
        make_board(self.board)

    def load(self, path=None, project="ProjectA", task="t_example"):
        return ingest(self.store, observe(path or self.board, project, task))

    def results(self):
        return query(self.store, "ProjectA", SHA)["evidence"]

    def test_idempotent_active_evidence_and_no_private_strings(self):
        self.assertEqual(self.load()["status"], "imported")
        before = self.store.read_bytes()
        self.assertEqual(self.load()["status"], "already_imported")
        self.assertEqual(self.store.read_bytes(), before)
        row, = self.results()
        self.assertEqual((row["taskId"], row["runId"], row["originSessionId"]), ("t_example", 1, "origin-5"))
        self.assertEqual((row["acceptanceEventId"], row["completedEventId"], row["requiredCheckCount"]), (3, 4, 1))
        for private in (b"PRIVATE SUMMARY", b"SECRET", b"private-check", b"/private", b"test.invalid"):
            self.assertNotIn(private, before)
        self.assertTrue(row["evidenceId"].startswith("kanban_"))

    def test_origin_session_is_selected_by_the_active_task_and_never_exposes_shared_session_tokens(self):
        self.load()
        sessions = self.root / "sessions.sqlite"
        with sqlite3.connect(sessions) as db:
            db.execute("""CREATE TABLE sessions(id TEXT PRIMARY KEY,input_tokens INTEGER,output_tokens INTEGER,
                       cache_read_tokens INTEGER,cache_write_tokens INTEGER,reasoning_tokens INTEGER,api_call_count INTEGER,
                       title TEXT)""")
            db.execute("INSERT INTO sessions VALUES('unrelated',4500,0,0,0,0,1,'PRIVATE PROMPT')")
        self.assertEqual(correlate_session(self.store, "ProjectA", SHA, "t_example", sessions)["status"],
                         "missing_from_session_snapshot")
        with sqlite3.connect(sessions) as db:
            db.execute("INSERT INTO sessions VALUES('origin-5',4500,0,0,0,0,1,'PRIVATE PROMPT')")
        matched = correlate_session(self.store, "ProjectA", SHA, "t_example", sessions)
        self.assertEqual((matched["status"], matched["role"], matched["originSessionId"]), ("observed", "task_origin", "origin-5"))
        self.assertNotIn("4500", json.dumps(matched))
        self.assertNotIn("PRIVATE PROMPT", json.dumps(matched))
        self.assertEqual(correlate_session(self.store, "ProjectB", SHA, "t_example", sessions)["status"],
                         "active_outcome_missing")

    def test_native_creation_project_and_task_registry_must_agree(self):
        with self.assertRaisesRegex(UsageError, "project_task_mismatch"):
            self.load(project="ProjectB")
        with sqlite3.connect(self.board) as db:
            db.execute("UPDATE task_events SET payload='{\"project_id\":\"ProjectB\"}' WHERE kind='created'")
        with self.assertRaisesRegex(UsageError, "project_task_mismatch"):
            self.load()
        self.assertFalse(self.store.exists())

    def test_distinct_projects_with_same_native_ids_remain_isolated(self):
        self.load()
        second = self.root / "other.db"
        make_board(second, project="ProjectB", pr="https://github.com/org/beta/pull/12")
        self.load(second, "ProjectB")
        self.assertEqual([row["repository"] for row in query(self.store, "ProjectB", SHA)["evidence"]], ["org/beta"])
        self.assertEqual([row["repository"] for row in self.results()], ["org/example"])
        different_revision = query(self.store, "ProjectA", "b" * 40)
        self.assertEqual(different_revision["evidence"], [])
        self.assertEqual(different_revision["repository"], "org/example")
        self.assertIsNone(query(self.store, "ProjectC", SHA)["repository"])
        self.assertEqual(query(self.store, "ProjectC", SHA)["evidence"], [])
        self.assertEqual(query(self.store, "ProjectA", SHA, "other")["evidence"], [])

    def test_project_cannot_be_rebound_to_another_repo(self):
        self.load()
        second = self.root / "other.db"
        make_board(second, task="t_other", pr="https://github.com/org/beta/pull/12")
        with self.assertRaisesRegex(UsageError, "project_repository_mismatch"):
            self.load(second, task="t_other")
        self.assertIsNone(inspect_task(self.store, "ProjectA", "t_other")["sourceWatermark"])
        self.assertEqual(len(self.results()), 1)

    def test_retry_supersedes_old_outcome_even_without_new_validation(self):
        baseline = self.root / "baseline.db"
        shutil.copyfile(self.board, baseline)
        self.load()
        with sqlite3.connect(self.board) as db:
            db.execute("UPDATE tasks SET status='running'")
            db.execute("INSERT INTO task_runs VALUES(2,'t_example','running',NULL,30,NULL,NULL,NULL)")
            db.execute("INSERT INTO task_events VALUES(5,'t_example',2,'claimed','{}',30)")
        self.load()
        self.assertEqual(self.results(), [])
        self.assertEqual(self.load(baseline)["status"], "older_snapshot")
        attempts = inspect_task(self.store, "ProjectA", "t_example")["attempts"]
        self.assertEqual([x["status"] for x in attempts], ["superseded", "candidate"])
        self.assertEqual(self.results(), [])

    def test_contradictory_history_rolls_back(self):
        self.load()
        original = self.results()
        with sqlite3.connect(self.board) as db:
            db.execute("UPDATE task_events SET created_at=1000 WHERE id=1")
            db.execute("INSERT INTO task_events VALUES(5,'t_example',NULL,'note',NULL,1500)")
        with self.assertRaisesRegex(UsageError, "divergent_task_history"):
            self.load()
        self.assertEqual(self.results(), original)

    def test_unverified_success_metadata_and_mismatched_checks_cannot_be_promoted(self):
        with sqlite3.connect(self.board) as db:
            db.execute("DELETE FROM task_events WHERE kind='pr_acceptance'")
            db.execute("UPDATE task_runs SET metadata=?", (json.dumps(receipt()),))
        self.load()
        self.assertEqual(self.results(), [])
        with sqlite3.connect(self.board) as db:
            forged = receipt()
            forged["checks"][0]["head_sha"] = "b" * 40
            db.execute("INSERT INTO task_events VALUES(5,'t_example',1,'pr_acceptance',?,22)", (json.dumps(forged),))
        with self.assertRaisesRegex(UsageError, "invalid_receipt"):
            self.load()
        self.assertEqual(self.results(), [])

    def test_receipt_requires_ordered_claim_acceptance_completion_and_terminal_run(self):
        with sqlite3.connect(self.board) as db:
            db.execute("UPDATE task_events SET id=5 WHERE kind='claimed'")
        self.load()
        self.assertEqual(self.results(), [])
        self.assertEqual(inspect_task(self.store, "ProjectA", "t_example")["attempts"][0]["status"], "rejected")

    def test_failed_checks_or_reopened_tasks_are_excluded(self):
        with sqlite3.connect(self.board) as db:
            db.execute("UPDATE task_events SET payload=? WHERE id=3", (json.dumps({"ok": False, "classification": "failure",
                       "head_sha": SHA, "pr_url": PR, "checks": []}),))
        self.load()
        self.assertEqual(self.results(), [])
        self.assertEqual(inspect_task(self.store, "ProjectA", "t_example")["attempts"][0]["status"], "rejected")

    def test_malformed_schema_sidecars_and_source_limits_fail_before_ingest(self):
        with sqlite3.connect(self.board) as db:
            db.execute("ALTER TABLE task_runs RENAME TO run_data")
            db.execute("CREATE VIEW task_runs AS SELECT * FROM run_data")
        with self.assertRaisesRegex(UsageError, "unsupported_kanban_schema"):
            self.load()
        (self.root / "board.db-wal").touch()
        with self.assertRaisesRegex(UsageError, "standalone_snapshot_required"):
            self.load()
        self.assertFalse(self.store.exists())

    def test_concurrency_and_enforced_storage_limits(self):
        self.load()
        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as threads:
            self.assertEqual(list(threads.map(lambda _: self.load()["status"], range(8))), ["already_imported"] * 8)
        other = self.root / "other.db"
        make_board(other, task="t_second")
        with patch("scripts.nexus_run_history.store.MAX_ROWS", 1), self.assertRaisesRegex(UsageError, "history_store_limit"):
            self.load(other, task="t_second")
        self.assertEqual(len(self.results()), 1)
        with patch("scripts.nexus_run_history.source.MAX_EVENTS", 3), self.assertRaisesRegex(UsageError, "task_history_incomplete"):
            self.load()

    def test_corrupt_store_rows_cannot_cross_project_response_boundaries(self):
        self.load()
        with sqlite3.connect(self.store) as db:
            row = self.results()[0]
            row["projectId"] = "ProjectB"
            row["private"] = "raw-secret"
            db.execute("UPDATE observations SET data=?", (json.dumps(row),))
        with self.assertRaisesRegex(UsageError, "invalid_history_observation"):
            self.results()
        with self.assertRaisesRegex(UsageError, "invalid_history_observation"):
            inspect_task(self.store, "ProjectA", "t_example")

    def test_name_swap_during_sqlite_open_cannot_initialize_external_file(self):
        observed = observe(self.board, "ProjectA", "t_example")
        victim = self.root / "victim"
        victim.touch()
        original = sqlite3.connect

        def swap_then_connect(database, *args, **kwargs):
            self.store.symlink_to(victim)
            self.assertEqual(database, ":memory:")
            return original(database, *args, **kwargs)

        with patch("scripts.nexus_run_history.store.sqlite3.connect", side_effect=swap_then_connect):
            with self.assertRaisesRegex(UsageError, "invalid_store_file"):
                ingest(self.store, observed)
        self.assertEqual(victim.read_bytes(), b"")

    def test_last_instant_destination_symlink_is_replaced_without_writing_its_target(self):
        victim = self.root / "victim"
        victim.write_bytes(b"external data")
        rename = os.replace

        def swap_then_rename(source, dest, **kwargs):
            self.store.symlink_to(victim)
            return rename(source, dest, **kwargs)

        with patch("scripts.nexus_run_history.files.os.replace", side_effect=swap_then_rename):
            self.load()
        self.assertFalse(self.store.is_symlink())
        self.assertEqual(victim.read_bytes(), b"external data")
        self.assertEqual(len(self.results()), 1)

    def test_replaced_parent_directory_and_sidecar_never_redirect_writes(self):
        observed = observe(self.board, "ProjectA", "t_example")
        parent = self.root / "private"
        parent.mkdir()
        foreign = self.root / "foreign"
        foreign.mkdir()
        self.store = parent / "history.sqlite"
        original = sqlite3.connect

        def swap_parent(database, *args, **kwargs):
            parent.rename(self.root / "detached")
            parent.symlink_to(foreign, target_is_directory=True)
            return original(database, *args, **kwargs)

        with patch("scripts.nexus_run_history.store.sqlite3.connect", side_effect=swap_parent), self.assertRaises(UsageError):
            ingest(self.store, observed)
        self.assertEqual(list(foreign.iterdir()), [])
        parent.unlink()
        (self.root / "detached").rename(parent)
        victim = foreign / "victim"
        victim.write_bytes(b"external")

        def plant_sidecar(database, *args, **kwargs):
            (parent / "history.sqlite-journal").symlink_to(victim)
            return original(database, *args, **kwargs)

        with patch("scripts.nexus_run_history.store.sqlite3.connect", side_effect=plant_sidecar), self.assertRaises(UsageError):
            ingest(self.store, observed)
        self.assertFalse(self.store.exists())
        self.assertEqual(victim.read_bytes(), b"external")

    def test_unrecognized_db_triggers_are_never_run(self):
        self.load()
        with sqlite3.connect(self.store) as db:
            db.execute("CREATE TRIGGER sqlitexspoof AFTER INSERT ON task_heads BEGIN DELETE FROM observations; END")
        with self.assertRaisesRegex(UsageError, "unsupported_history_store"):
            self.load()

    def test_cli_export_and_protected_store(self):
        def cli(*args):
            return subprocess.run([sys.executable, "-B", "-m", "scripts.nexus_run_history", *args],
                                  cwd=Path(__file__).resolve().parents[2], capture_output=True, text=True)
        common = ["--store", str(self.store), "--project-id", "ProjectA"]
        inserted = cli("ingest", *common, "--kanban", str(self.board), "--task-id", "t_example")
        self.assertEqual(inserted.returncode, 0, inserted.stderr)
        exported = cli("export", *common, "--revision", SHA)
        self.assertEqual(exported.returncode, 0, exported.stderr)
        self.assertEqual(json.loads(exported.stdout), {"schemaVersion": 1, "exampleType": "verified_pr_check_outcome",
                                                       "evidence": self.results()[0]})
        self.assertEqual(cli("export", *common, "--revision", "b" * 40).stdout, "")
        self.assertEqual(cli("query", *common, "--revision", "branch").returncode, 1)
        self.store.unlink()
        self.store.symlink_to(self.board)
        source = self.board.read_bytes()
        with self.assertRaisesRegex(UsageError, "invalid_store_file"):
            self.load()
        self.assertEqual(self.board.read_bytes(), source)
